from collections import defaultdict

orders = [("ada", 30), ("lin", 12), ("ada", 5)]
by_customer = defaultdict(list)
for name, amount in orders:
    by_customer[name].append(amount)   # missing key -> new empty list

print(dict(by_customer))   # {'ada': [30, 5], 'lin': [12]}

totals = defaultdict(int)  # int() returns 0
for name, amount in orders:
    totals[name] += amount
print(totals["ada"])       # 35
